  if (window.matchMedia('(pointer: fine)').matches) hero.addEventListener('pointermove', (event) => { const rect = hero.getBoundingClientRect(); pointer = { x: (event.clientX - rect.left) / rect.width, y: (event.clientY - rect.top) / rect.height }; }, { passive: true });
